import sys, json, zipfile, re
from xml.etree import ElementTree as ET

path = sys.argv[1]
NS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"

with zipfile.ZipFile(path) as z:
    names = z.namelist()
    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall(f"{NS}si"):
            shared.append("".join(t.text or "" for t in si.iter(f"{NS}t")))
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = [(s.get("name"), s.get("sheetId")) for s in wb.iter(f"{NS}sheet")]
    out = {"sheets": sheets, "parts": [n for n in names if n.startswith("xl/worksheets")]}
    cells = {}
    for part in out["parts"]:
        root = ET.fromstring(z.read(part))
        for c in root.iter(f"{NS}c"):
            ref, t = c.get("r"), c.get("t")
            v = c.find(f"{NS}v")
            isel = c.find(f"{NS}is")
            if v is not None:
                val = shared[int(v.text)] if t == "s" else v.text
            elif isel is not None:
                val = "".join(x.text or "" for x in isel.iter(f"{NS}t"))
            else:
                val = None
            if val is not None:
                cells[ref] = val
    out["cells"] = cells
    out["backup_has_old"] = "草稿" in json.dumps(cells, ensure_ascii=False)

print(json.dumps(out, ensure_ascii=True, sort_keys=True))

